import { ArrowBigUp, Scroll } from 'lucide-react'
import React from 'react'
import RevealToScroll from './RevealToScroll'

const ScrollToTop = () => {
  return <div >
    <button onClick={()=> window.scrollTo({top:0,behavior:"smooth"})} className=' fixed bottom-16 right-16 z-50 border-2 rounded-full w-16 h-16 flex justify-center items-center bg-text/20 hover:bg-text/50 cursor-pointer '> <ArrowBigUp className='w-8 h-8'/></button>
  </div>
  
}

export default ScrollToTop;
